import { test } from '@playwright/test'
import { opGoto, opClick, opFill, opPress, opSeen } from './prims'

test('@journey:suite @smoke Try to submit contact form with excessively long name', async ({ page }) => {
  await opGoto(page, '/contact')
  await opFill(page, 'Name', 'A very long name that stretches well beyond reasonable lengths and includes many special characters like !@#$%^&*()_+{}|:<>?[]\\;\',./`~')
  await opFill(page, 'Email', 'test@example.com')
  await opFill(page, 'Message', 'Short message.')
  await opPress(page, 'Enter')
  await opSeen(page, 'dialog', 'Thank you for your message')
})
